Here's a Python implementation of the Template Method pattern for sorting algorithms. It defines a SortAlgorithm base with a template sort method that relies on abstract compare and swap hooks, plus concrete BubbleSort and SelectionSort implementations.

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        # Work on a copy to avoid mutating external input unexpectedly
        self.data = list(data)

    @abstractmethod
    def compare(self, a: Any, b: Any) -> bool:
        """
        Return True if a should come after b (i.e., a > b) for ascending order.
        This is the ordering hook.
        """
        pass

    @abstractmethod
    def swap(self, i: int, j: int) -> None:
        """Swap elements at indices i and j."""
        pass

    def sort(self) -> List[Any]:
        """
        Template method: defines the generic sorting skeleton using
        compare and swap. Concrete subclasses may override sort(), but the
        default implementation demonstrates the Template Method pattern.
        """
        n = len(self.data)
        for i in range(n - 1):
            for j in range(n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)
        return self.data

class BubbleSort(SortAlgorithm):
    def compare(self, a: Any, b: Any) -> bool:
        # For ascending order, swap if a > b
        return a > b

    def swap(self, i: int, j: int) -> None:
        self.data[i], self.data[j] = self.data[j], self.data[i]

class SelectionSort(SortAlgorithm):
    def compare(self, a: Any, b: Any) -> bool:
        # Keeps the same meaning: True if a > b
        return a > b

    def swap(self, i: int, j: int) -> None:
        self.data[i], self.data[j] = self.data[j], self.data[i]

    def sort(self) -> List[Any]:
        # Implement selection sort using the compare/swap hooks
        n = len(self.data)
        for i in range(n - 1):
            min_idx = i
            for j in range(i + 1, n):
                # If data[min_idx] > data[j], then j is the new minimum
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)
        return self.data

# Tests
if __name__ == "__main__":
    # Numeric test
    arr_numbers = [64, 34, 25, 12, 22, 11, 90]
    bubble = BubbleSort(arr_numbers)
    print("BubbleSort numbers:", bubble.sort())

    arr_numbers2 = [64, 34, 25, 12, 22, 11, 90]
    selection = SelectionSort(arr_numbers2)
    print("SelectionSort numbers:", selection.sort())

    # String test
    arr_strings = ["zeta", "alpha", "gamma", "beta"]
    bubble_str = BubbleSort(arr_strings)
    print("BubbleSort strings:", bubble_str.sort())

    arr_strings2 = ["zeta", "alpha", "gamma", "beta"]
    selection_str = SelectionSort(arr_strings2)
    print("SelectionSort strings:", selection_str.sort())
